import 'package:flutter/material.dart';import 'data/app_database.dart';import 'features/products_page.dart';import 'features/entity_pages.dart';import 'features/sales_page.dart';import 'features/purchases_page.dart';import 'features/reports_page.dart';import 'features/settings_page.dart';
Future<void> main()async{WidgetsFlutterBinding.ensureInitialized();await AppDatabase.instance.database;runApp(const QamvioApp());}
class QamvioApp extends StatelessWidget{const QamvioApp({super.key});@override Widget build(BuildContext context)=>MaterialApp(debugShowCheckedModeBanner:false,title:'QAMVIO POS',theme:ThemeData(useMaterial3:true,colorSchemeSeed:const Color(0xFF174EA6)),home:const DashboardPage());}
class DashboardPage extends StatefulWidget{const DashboardPage({super.key});@override State<DashboardPage> createState()=>_D();}
class _D extends State<DashboardPage>{Map<String,num> totals={};@override void initState(){super.initState();refresh();}Future<void> refresh()async{totals=await AppDatabase.instance.dashboardTotals();if(mounted)setState((){});}void open(Widget p)=>Navigator.push(context,MaterialPageRoute(builder:(_)=>p)).then((_)=>refresh());
@override Widget build(BuildContext context){final m=<({IconData i,String n,Widget? p})>[(i:Icons.point_of_sale,n:'Sales & Invoice',p:const SalesPage()),(i:Icons.inventory_2,n:'Products & Inventory',p:const ProductsPage()),(i:Icons.shopping_cart_checkout,n:'Purchases',p:const PurchasesPage()),(i:Icons.people,n:'Customers',p:const EntityPage(kind:EntityKind.customers)),(i:Icons.local_shipping,n:'Suppliers',p:const EntityPage(kind:EntityKind.suppliers)),(i:Icons.payments,n:'Expenses & Accounts',p:const EntityPage(kind:EntityKind.expenses)),(i:Icons.local_gas_station,n:'Oil / Fuel Pump',p:const EntityPage(kind:EntityKind.fuelTanks)),(i:Icons.medication,n:'Pharmacy',p:const ProductsPage()),(i:Icons.assessment,n:'Reports',p:const ReportsPage()),(i:Icons.settings,n:'Business Settings',p:const SettingsPage())];return Scaffold(appBar:AppBar(title:const Text('QAMVIO POS — Flutter')),body:RefreshIndicator(onRefresh:refresh,child:ListView(padding:const EdgeInsets.all(16),children:[Wrap(spacing:8,runSpacing:8,children:[stat('Sales','${totals['sales']??0}'),stat('Products','${totals['products']??0}'),stat('Customers','${totals['customers']??0}'),stat('Revenue','${totals['revenue']??0}'),stat('Expenses','${totals['expenses']??0}')]),const SizedBox(height:16),GridView.builder(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),gridDelegate:const SliverGridDelegateWithMaxCrossAxisExtent(maxCrossAxisExtent:220,childAspectRatio:1.35,crossAxisSpacing:12,mainAxisSpacing:12),itemCount:m.length,itemBuilder:(c,i){final x=m[i];return Card(child:InkWell(onTap:()=>x.p==null?open(x.p!),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(x.i,size:34),const SizedBox(height:8),Text(x.n,textAlign:TextAlign.center)])));})]))));}Widget stat(String a,String b)=>Card(child:Padding(padding:const EdgeInsets.all(10),child:Column(children:[Text(a),Text(b,style:const TextStyle(fontWeight:FontWeight.bold,fontSize:18))])));}
